fam.strMots.capitalise-phrase.01.referenceSolution:
String[] liste = message.split(" ");
String resultat = "";
for (int i = 0; i < liste.length; i++) {
    String m = liste[i];
    m = m.substring(0, 1).toUpperCase() + m.substring(1).toLowerCase();
    if (i > 0) {
        resultat = resultat + " ";
    }
    resultat = resultat + m;
}

